  const result = createInvoice({
    customerId: 'C-001', // gold tier (5% discount)
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
    ],
  });
  const invoice = result.value;
  const text = renderInvoiceText(invoice);

  assert.match(text, /Subtotal: €/, 'Should show Subtotal');
  assert.match(text, /Discount: -€/, 'Should show Discount');
  assert.match(text, /VAT: €/, 'Should show VAT');
  assert.match(text, /Total: €/, 'Should show Total');
});

test('renderInvoiceText VAT line above Total', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 1 },
    ],
  });
  const invoice = result.value;
  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

