  const expectedVat = Math.round(10000 * 9 / 100); // 900
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.vat, 900);
  assert.equal(totals.total, 10900);
});

test('invoiceTotals with multiple lines different VAT rates', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, vatRate: 21 },
      { qty: 10, unitPrice: 1000, vatRate: 9 },
      { qty: 10, unitPrice: 1000, vatRate: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const vat1 = Math.round(10000 * 21 / 100); // 2100
  const vat2 = Math.round(10000 * 9 / 100); // 900
  const vat3 = 0;

  assert.equal(totals.subtotal, 30000);
  assert.equal(totals.vat, vat1 + vat2 + vat3); // 3000
  assert.equal(totals.total, 30000 + 3000); // 33000
});

test('invoiceTotals VAT with discount and VAT combined', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 10, vatRate: 21 },
      { qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 9 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Line 1: 10000, discount 1000, after discount 9000, VAT 1890
  const vat1 = Math.round(9000 * 21 / 100); // 1890
  // Line 2: 10000, no discount, VAT 900
  const vat2 = Math.round(10000 * 9 / 100); // 900

  assert.equal(totals.subtotal, 20000);
  assert.equal(totals.discount, 1000);
  assert.equal(totals.vat, vat1 + vat2); // 2790
  assert.equal(totals.total, 20000 - 1000 + 2790); // 21790
});

test('invoiceTotals VAT rounds per line', () => {
  const invoice = {
    lines: [
      { qty: 3, unitPrice: 333, vatRate: 21 },
      { qty: 3, unitPrice: 333, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Each line: 999, VAT 209.79 rounds to 210
  const vat1 = Math.round(999 * 21 / 100); // 210
  const vat2 = Math.round(999 * 21 / 100); // 210

  assert.equal(totals.vat, vat1 + vat2); // 420, not the whole total VAT
});

test('invoiceTotals with enriched invoice from createInvoice includes VAT', () => {
  const result = createInvoice({
    customerId: 'C-002', // standard tier, no discount
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'DEV-HOUR', qty: 1 },
    ],
  });
  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  // DES-HOUR: 21% VAT, DEV-HOUR: 21% VAT
  const line1 = 2 * 8500; // 17000
  const line1Vat = Math.round(line1 * 21 / 100); // 3570
  const line2 = 1 * 9500; // 9500
  const line2Vat = Math.round(line2 * 21 / 100); // 1995

  assert.equal(totals.subtotal, 26500);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, line1Vat + line2Vat); // 5565
  assert.equal(totals.total, 26500 + 5565); // 32065
});

