  assert.equal(totals.subtotal, 30000);
  assert.equal(totals.vat, vat1 + vat2 + vat3); // 3000
  assert.equal(totals.total, 30000 + 3000); // 33000
});

test('invoiceTotals VAT with discount and VAT combined', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 10, vatRate: 21 },
      { qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 9 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Line 1: 10000, discount 1000, after discount 9000, VAT 1890
  const vat1 = Math.round(9000 * 21 / 100); // 1890
  // Line 2: 10000, no discount, VAT 900
  const vat2 = Math.round(10000 * 9 / 100); // 900

  assert.equal(totals.subtotal, 20000);
  assert.equal(totals.discount, 1000);
  assert.equal(totals.vat, vat1 + vat2); // 2790
  assert.equal(totals.total, 20000 - 1000 + 2790); // 21790
});

test('invoiceTotals VAT rounds per line', () => {
  const invoice = {
    lines: [
      { qty: 3, unitPrice: 333, vatRate: 21 },
      { qty: 3, unitPrice: 333, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Each line: 999, VAT 209.79 rounds to 210
  const vat1 = Math.round(999 * 21 / 100); // 210
  const vat2 = Math.round(999 * 21 / 100); // 210

  assert.equal(totals.vat, vat1 + vat2); // 420, not the whole total VAT
});

